import React, { useEffect, useMemo, useRef, useState } from "react";
import Timeline from "./components/Timeline";
import VideoPreview from "./components/VideoPreview";

const SAMPLE_VIDEO = "https://www.w3schools.com/html/mov_bbb.mp4";

const createTimelineThumbnails = (duration) => {
  const total = duration > 0 ? duration : 30;
  const count = 14;
  return Array.from({ length: count }, (_, index) => {
    const progress = count > 1 ? index / (count - 1) : 0;
    return {
      id: index,
      label: `Scene ${index + 1}`,
      time: parseFloat((total * progress).toFixed(1)),
      hue: 340 - progress * 120,
    };
  });
};

export default function App() {
  const videoRef = useRef(null);
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  const thumbnails = useMemo(() => createTimelineThumbnails(duration), [duration]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handlePlay = () => setIsPlaying(true);
    const handlePause = () => setIsPlaying(false);

    video.addEventListener("play", handlePlay);
    video.addEventListener("pause", handlePause);

    return () => {
      video.removeEventListener("play", handlePlay);
      video.removeEventListener("pause", handlePause);
    };
  }, []);

  const handleTogglePlay = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) {
      video.play().catch(() => {});
    } else {
      video.pause();
    }
  };

  const handleTimeUpdate = (time) => {
    setCurrentTime(time);
  };

  const handleDurationChange = (time) => {
    setDuration(time);
  };

  const handleSeek = (time) => {
    const video = videoRef.current;
    if (!video) return;
    const nextTime = Math.max(0, Math.min(time, duration || video.duration || 0));
    video.currentTime = nextTime;
    setCurrentTime(nextTime);
  };

  return (
    <div className="min-h-screen bg-[#0f0f0f] px-4 py-6 text-slate-100">
      <div className="mx-auto flex w-full max-w-6xl flex-col gap-6">
        <section className="rounded-[32px] border border-white/10 bg-slate-950/70 p-5 shadow-soft backdrop-blur-xl">
          <div className="mb-6 text-center">
            <p className="mx-auto max-w-2xl text-sm uppercase tracking-[0.35em] text-pink-300/80">Mobile-first video editor</p>
            <h1 className="mt-4 text-3xl font-semibold text-white sm:text-4xl">InShot-inspired cinematic workspace</h1>
            <p className="mt-3 text-slate-400">Smooth playback controls, touch-friendly timeline scrubbing, and a minimal dark editing canvas.</p>
          </div>

          <VideoPreview
            ref={videoRef}
            src={SAMPLE_VIDEO}
            isPlaying={isPlaying}
            onTogglePlay={handleTogglePlay}
            onTimeUpdate={handleTimeUpdate}
            onDuration={handleDurationChange}
          />
        </section>

        <Timeline duration={duration} currentTime={currentTime} thumbnails={thumbnails} onSeek={handleSeek} onAddClip={() => {}} />
      </div>
    </div>
  );
}
